// Music catalogue (files in audio/music/). Each loop file is pre-cut so that [0, loop] repeats seamlessly
// (bar-aligned, the tail crossfade is baked into the head); `loop` also guards against mp3 end padding.
// gain evens loudness between tracks (all about -15 LUFS). Prompts and cut points: docs/notes/audio.md.
// Only entries whose file is in manifest.js (generated by gen_manifest.mjs) are exported, so the engine never
// requests a file that does not ship.
import { FILES } from './manifest.js';

const ALL_TRACKS = {
  // v2 (audio-3, YuE2 via Music Studio project aa890ebe98). Gains bring each loop to about -15 LUFS (hub -16, calmer).
  hub: { file: 'hub.mp3', loop: 54.8057, gain: 0.55 },        // 87da33b74a, 20 bars @ 87.5
  map: { file: 'map.mp3', loop: 43.2017, gain: 1 },           // 26bd2e3494 (B), 18 bars @ 99.9, drum-led, -18 LUFS: calmer than battle
  battle_1: { file: 'battle_1.mp3', loop: 20.7665, gain: 1.2 }, // a9ce9dc6b7 (B), 6 bars @ 69.5 (half-time 139)
  battle_2: { file: 'battle_2.mp3', loop: 55.4003, gain: 0.55 }, // e6bae75015, 28 bars @ 121.6
  battle_3: { file: 'battle_3.mp3', loop: 62.4911, gain: 0.77 }, // 72e3392185, 39 bars @ 149.6
  battle_4: { file: 'battle_4.mp3', loop: 53.896, gain: 0.79 }, // 71a5cba878 (B), 29 bars @ 129
  boss: { file: 'boss.mp3', loop: 26.7248, gain: 0.75 },      // b849d54b8b (B), 12 bars @ 107.8
  rift: { file: 'rift.mp3', loop: 56.1812, gain: 0.73 },      // d6f401c8ed, 14 bars @ 59.8
};

const ALL_STINGS = {
  victory: { file: 'sting_victory.mp3', gain: 1 },
  defeat: { file: 'sting_defeat.mp3', gain: 1 },
  reveal: { file: 'sting_reveal.mp3', gain: 1 },
  crowd: { file: 'crowd.mp3', gain: 1, bus: 'sfx' },
};

// music(name) accepts a track id or one of these states; a state rotates through its list each time it starts.
const ALL_STATES = {
  menu: ['hub'],
  map: ['map'],
  battle: ['battle_1', 'battle_2', 'battle_3', 'battle_4'],
  boss: ['boss', 'battle_3'],
  rift: ['rift', 'battle_2'],
};

// Route (first hash segment) -> music state. 'battle' is chosen by forBattle(); null = leave the music as it is.
export const ROUTES = {
  hub: 'menu', squad: 'menu', barracks: 'menu', collection: 'menu', workshop: 'menu', unit: 'menu', hq: 'menu',
  recruit: 'menu', arena: 'menu', events: 'menu', settings: 'menu', results: 'menu',
  map: 'map', chapters: 'map', formation: 'map',
  battle: null,
};

export const filePath = (e) => (e.bus === 'sfx' ? 'sfx/' : 'music/') + e.file;
const ships = (e) => Object.prototype.hasOwnProperty.call(FILES, filePath(e));
const pick = (o) => Object.fromEntries(Object.entries(o).filter(([, e]) => ships(e)));

export const TRACKS = pick(ALL_TRACKS);
export const STINGS = pick(ALL_STINGS);
// A state keeps only shipped tracks; boss/rift fall back to the next entry when their own file is missing.
export const STATES = Object.fromEntries(Object.entries(ALL_STATES).map(([k, list]) => {
  const ok = list.filter((id) => TRACKS[id]);
  return [k, k === 'boss' || k === 'rift' ? ok.slice(0, 1) : ok];
}).filter(([, l]) => l.length));
export const UNSHIPPED = [...Object.keys(ALL_TRACKS).filter((k) => !TRACKS[k]), ...Object.keys(ALL_STINGS).filter((k) => !STINGS[k])];
